import Foundation
import Metal

/// Tessellation emulation for Apple GPUs without the Metal 3 tessellator (A9/A10,
/// iOS 14/15 floor). See Shaders/Tessellation.metal for the kernel ABI and the
/// documented approximations.
///
/// Responsibilities are split deliberately:
/// - This class generates the domain sample positions and triangle-list indices on
///   the CPU from the tessellation factor buffer (A9 uses shared storage, so factors
///   produced by a compute pass can be read after the producing encoder completes).
/// - The domain kernel - generated by Tools/metal_retarget.py from the app's
///   post-tessellation vertex function, or one of the built-in demo kernels - runs on
///   the GPU and produces the final vertex stream.
/// - The caller then issues an ordinary `drawIndexedPrimitives` with the returned
///   buffers. The retarget tool rewrites `drawPatches` calls into this sequence.
public final class TessellationEmulator {
    public enum PatchType: Int {
        case triangle = 0
        case quad = 1
    }

    public enum PartitionMode: Int {
        case integer = 0
        case pow2 = 1
        case fractionalOdd = 2
        case fractionalEven = 3
    }

    public enum Winding: Int {
        case clockwise = 0
        case counterClockwise = 1
    }

    /// A single tessellated draw request. Mirrors the fields of
    /// MTLRenderCommandEncoder.drawPatches that affect geometry, minus the pipeline
    /// plumbing the tool rewrite replaces with an ordinary indexed draw.
    public struct DrawRequest {
        public let patchType: PatchType
        public let partitionMode: PartitionMode
        public let winding: Winding
        public let patchCount: Int
        /// Bytes between control points in `controlPointBuffer`.
        public let controlPointStride: Int
        /// Bytes between vertex structs in the domain kernel output.
        public let vertexStride: Int
        public let controlPointBuffer: MTLBuffer
        public let controlPointOffset: Int
        /// Shared-storage factor buffer in MTLTessellationFactorFormat.half layout:
        /// triangle patches store 4 halfs per patch (3 edges + inside), quad patches
        /// store 6 halfs per patch (4 edges + 2 inside).
        public let factorBuffer: MTLBuffer
        public let factorOffset: Int
        /// True when a GPU pass wrote the factors in the same command buffer. The
        /// emulator must then wait for that pass (waitUntilCompleted) before the CPU
        /// readback - an explicit, documented stall on the emulated path.
        public let factorsAreGpuWritten: Bool

        public init(patchType: PatchType,
                    partitionMode: PartitionMode,
                    winding: Winding,
                    patchCount: Int,
                    controlPointStride: Int,
                    vertexStride: Int,
                    controlPointBuffer: MTLBuffer,
                    controlPointOffset: Int = 0,
                    factorBuffer: MTLBuffer,
                    factorOffset: Int = 0,
                    factorsAreGpuWritten: Bool = false) {
            self.patchType = patchType
            self.partitionMode = partitionMode
            self.winding = winding
            self.patchCount = patchCount
            self.controlPointStride = controlPointStride
            self.vertexStride = vertexStride
            self.controlPointBuffer = controlPointBuffer
            self.controlPointOffset = controlPointOffset
            self.factorBuffer = factorBuffer
            self.factorOffset = factorOffset
            self.factorsAreGpuWritten = factorsAreGpuWritten
        }
    }

    /// Everything the caller needs for the replacement indexed draw.
    public struct TessellatedDraw {
        public let vertexBuffer: MTLBuffer
        public let vertexCount: Int
        public let indexBuffer: MTLBuffer
        public let indexCount: Int
        /// What was approximated for this draw (integer clamp, edge averaging, ...).
        public let approximations: [String]
        public let commandBuffer: MTLCommandBuffer
    }

    public let device: MTLDevice
    /// Maximum tessellation factor the emulated path honors (family limit: 16 on
    /// Apple3, 64 on Apple4 and newer).
    public let maxTessellationFactor: Int
    /// True when the device could run the native Metal 3 tessellation path instead;
    /// the retarget tool emits the native branch in that case.
    public private(set) var nativePathAvailable: Bool = false

    private struct TopologyKey: Hashable {
        let patchType: Int
        let winding: Int
        let patchCount: Int
        let factors: [UInt16]
    }

    private struct Topology {
        let samplesBuffer: MTLBuffer
        let indexBuffer: MTLBuffer
        let samplesPerPatch: Int
        let indexCount: Int
        let approximations: [String]
    }

    private var topologyCache: [TopologyKey: Topology] = [:]
    private var domainLibrary: MTLLibrary?

    public init(device: MTLDevice, capabilities: BridgeCapabilities, maxTessellationFactor: Int) {
        self.device = device
        self.maxTessellationFactor = maxTessellationFactor
        self.nativePathAvailable = capabilities.supportsMetal3
    }

    // MARK: - Public entry point

    /// Tessellates the request and encodes the domain kernel on `commandBuffer`.
    /// Returns the draw parameters for the replacement indexed draw.
    public func tessellate(_ request: DrawRequest,
                           domainFunction: MTLFunction,
                           extraBuffers: [(index: Int, buffer: MTLBuffer, offset: Int)] = [],
                           into commandBuffer: MTLCommandBuffer) throws -> TessellatedDraw {
        guard request.patchCount > 0 else {
            throw BridgeError.invalidArgument("Tessellation requires at least one patch.")
        }
        guard request.controlPointStride > 0, request.vertexStride > 0 else {
            throw BridgeError.invalidArgument("Control point and vertex strides must be positive.")
        }

        if request.factorsAreGpuWritten {
            // Honest cost: the emulated path reads factors on the CPU, so GPU-written
            // factors force a command-buffer completion before encoding continues.
            commandBuffer.waitUntilCompleted()
        }

        let topology = try self.topology(for: request)
        let totalSamples = topology.samplesPerPatch * request.patchCount
        let vertexBytes = totalSamples * request.vertexStride
        try self.validateAllocation(vertexBytes)

        guard let vertexBuffer = device.makeBuffer(length: max(vertexBytes, 16), options: .storageModeShared) else {
            throw BridgeError.allocationFailed("Failed to allocate \(vertexBytes) bytes for tessellated vertices.")
        }
        guard let paramsBuffer = device.makeBuffer(length: MemoryLayout<TessDomainParamsLayout>.size, options: .storageModeShared) else {
            throw BridgeError.allocationFailed("Failed to allocate the domain parameter buffer.")
        }

        var params = TessDomainParamsLayout()
        params.patchCount = UInt32(request.patchCount)
        params.controlPointsPerPatch = UInt32(request.patchType == .quad ? 4 : 3)
        params.samplesPerPatch = UInt32(topology.samplesPerPatch)
        params.controlPointStride = UInt32(request.controlPointStride)
        params.vertexStride = UInt32(request.vertexStride)
        params.patchType = UInt32(request.patchType.rawValue)
        paramsBuffer.contents().copyMemory(from: &params, byteCount: MemoryLayout<TessDomainParamsLayout>.size)

        guard let encoder = commandBuffer.makeComputeCommandEncoder() else {
            throw BridgeError.operationFailed("Could not create a compute encoder for the domain kernel.")
        }
        let width = max(1, totalSamples)
        let threads = MTLSize(width: width, height: 1, depth: 1)
        let pipeline = try self.pipelineState(for: domainFunction)
        encoder.setComputePipelineState(pipeline)
        encoder.setBuffer(paramsBuffer, offset: 0, index: 0)
        encoder.setBuffer(request.controlPointBuffer, offset: request.controlPointOffset, index: 1)
        encoder.setBuffer(topology.samplesBuffer, offset: 0, index: 2)
        encoder.setBuffer(vertexBuffer, offset: 0, index: 3)
        for extra in extraBuffers {
            encoder.setBuffer(extra.buffer, offset: extra.offset, index: extra.index)
        }
        let groupSize = self.groupSize(for: pipeline, threads: threads)
        encoder.dispatchThreads(threads, threadsPerThreadgroup: groupSize)
        encoder.endEncoding()

        return TessellatedDraw(vertexBuffer: vertexBuffer,
                               vertexCount: totalSamples,
                               indexBuffer: topology.indexBuffer,
                               indexCount: topology.indexCount,
                               approximations: topology.approximations,
                               commandBuffer: commandBuffer)
    }

    /// Loads one of the built-in demo domain kernels from the framework metallib.
    public func makeDemoDomainFunction(patchType: PatchType) throws -> MTLFunction {
        let library = try self.frameworkLibrary()
        let name = patchType == .quad ? "mb_tess_demo_domain_quad" : "mb_tess_demo_domain_triangle"
        guard let function = library.makeFunction(name: name) else {
            throw BridgeError.unsupported("Framework metallib is missing \(name).")
        }
        return function
    }

    // MARK: - Topology generation (CPU)

    private func topology(for request: DrawRequest) throws -> Topology {
        let factors = try self.readFactors(request)
        let key = TopologyKey(patchType: request.patchType.rawValue,
                              winding: request.winding.rawValue,
                              patchCount: request.patchCount,
                              factors: factors)
        if let cached = topologyCache[key] {
            return cached
        }
        var approximations: [String] = []
        if request.partitionMode != .integer {
            approximations.append("""
            Partition mode \(request.partitionMode) is approximated by integer \
            partitioning on the emulated path; Apple's tessellator honors fractional \
            and pow2 modes exactly.
            """)
        }
        let built: Topology
        switch request.patchType {
        case .quad:
            built = try self.buildQuadTopology(factors: factors, request: request, approximations: &approximations)
        case .triangle:
            built = try self.buildTriangleTopology(factors: factors, request: request, approximations: &approximations)
        }
        topologyCache[key] = built
        return built
    }

    private func readFactors(_ request: DrawRequest) throws -> [UInt16] {
        let halfsPerPatch = request.patchType == .quad ? 6 : 4
        let count = halfsPerPatch * request.patchCount
        let base = request.factorBuffer.contents().advanced(by: request.factorOffset)
        guard request.factorOffset + count * 2 <= request.factorBuffer.length else {
            throw BridgeError.invalidArgument("""
            Factor buffer is too small: needs \(count * 2) bytes at offset \
            \(request.factorOffset), buffer holds \(request.factorBuffer.length) bytes.
            """)
        }
        let pointer = base.bindMemory(to: UInt16.self, capacity: count)
        return (0..<count).map { pointer[$0] }
    }

    private func buildQuadTopology(factors: [UInt16], request: DrawRequest, approximations: inout [String]) throws -> Topology {
        // Layout: edges 0..3 then inside 0 (u) and 1 (v), as half floats.
        let clampNote = """
        Per-edge tessellation factors are averaged across opposite edges and inside \
        factors are clamped to \(self.maxTessellationFactor) (Apple3 limit) on the \
        emulated path; Apple's tessellator honors per-edge factors exactly.
        """
        var sawEdgeMismatch = false
        var sawClamp = false
        var samples: [Float] = []
        var indices: [UInt32] = []

        for patch in 0..<request.patchCount {
            let base = patch * 6
            let e0 = self.partitionCount(factors[base + 0])
            let e1 = self.partitionCount(factors[base + 1])
            let e2 = self.partitionCount(factors[base + 2])
            let e3 = self.partitionCount(factors[base + 3])
            let insideU = self.partitionCount(factors[base + 4])
            let insideV = self.partitionCount(factors[base + 5])

            var iu = max(1, (e0 + e2 + 1) / 2)
            var iv = max(1, (e1 + e3 + 1) / 2)
            iu = min(iu, max(1, self.maxTessellationFactor))
            iv = min(iv, max(1, self.maxTessellationFactor))
            if e0 != e2 || e1 != e3 || insideU != iu || insideV != iv { sawEdgeMismatch = true }
            if iu >= self.maxTessellationFactor || iv >= self.maxTessellationFactor { sawClamp = true }

            let rowVerts = iu + 1
            for v in 0...iv {
                for u in 0...iu {
                    samples.append(Float(u) / Float(iu))
                    samples.append(Float(v) / Float(iv))
                }
            }
            for y in 0..<iv {
                for x in 0..<iu {
                    let a = UInt32(y * rowVerts + x)
                    let b = a + 1
                    let c = a + UInt32(rowVerts)
                    let d = c + 1
                    if request.winding == .clockwise {
                        indices += [a, c, b, b, c, d]
                    } else {
                        indices += [a, b, c, b, d, c]
                    }
                }
            }
        }
        if sawEdgeMismatch { approximations.append(clampNote) }
        if sawClamp {
            approximations.append("Tessellation factors were clamped to the \(self.maxTessellationFactor) family maximum.")
        }
        return try self.makeTopology(samples: samples,
                                     indices: indices,
                                     patchCount: request.patchCount,
                                     samplesPerPatchOverride: samples.count / max(1, request.patchCount) / 2,
                                     isBarycentric: false,
                                     approximations: approximations,
                                     request: request)
    }

    private func buildTriangleTopology(factors: [UInt16], request: DrawRequest, approximations: inout [String]) throws -> Topology {
        // Layout: edges 0..2 then inside, as half floats. The emulated path samples
        // the barycentric lattice uniformly; edge factors are averaged.
        var sawEdgeMismatch = false
        var samples: [Float] = []
        var indices: [UInt32] = []

        for patch in 0..<request.patchCount {
            let base = patch * 4
            let e0 = self.partitionCount(factors[base + 0])
            let e1 = self.partitionCount(factors[base + 1])
            let e2 = self.partitionCount(factors[base + 2])
            let inside = self.partitionCount(factors[base + 3])

            var i = max(1, (e0 + e1 + e2 + 1) / 3)
            i = min(i, max(1, self.maxTessellationFactor))
            if e0 != e1 || e1 != e2 || inside != i { sawEdgeMismatch = true }

            let latticeStart = samples.count / 3
            for a in 0...i {
                for b in 0...(i - a) {
                    samples.append(Float(a) / Float(i))
                    samples.append(Float(b) / Float(i))
                    samples.append(Float(i - a - b) / Float(i))
                }
            }
            func index(_ a: Int, _ b: Int) -> UInt32 {
                let rowStart = a * (2 * i + 3 - a) / 2
                return UInt32(latticeStart + rowStart + b)
            }
            for a in 0..<i {
                for b in 0..<max(0, i - a) {
                    let v00 = index(a, b)
                    let v10 = index(a + 1, b)
                    let v01 = index(a, b + 1)
                    let v11 = index(a + 1, b + 1)
                    if request.winding == .clockwise {
                        indices += [v00, v10, v01]
                        if a + b + 2 <= i { indices += [v10, v11, v01] }
                    } else {
                        indices += [v00, v01, v10]
                        if a + b + 2 <= i { indices += [v10, v01, v11] }
                    }
                }
            }
        }
        if sawEdgeMismatch {
            approximations.append("""
            Per-edge tessellation factors are averaged across the three edges and the \
            inside factor is clamped to \(self.maxTessellationFactor) on the emulated \
            path; Apple's tessellator honors per-edge factors exactly.
            """)
        }
        return try self.makeTopology(samples: samples,
                                     indices: indices,
                                     patchCount: request.patchCount,
                                     samplesPerPatchOverride: samples.count / 3 / max(1, request.patchCount),
                                     isBarycentric: true,
                                     approximations: approximations,
                                     request: request)
    }

    private func makeTopology(samples: [Float],
                              indices: [UInt32],
                              patchCount: Int,
                              samplesPerPatchOverride: Int,
                              isBarycentric: Bool,
                              approximations: [String],
                              request: DrawRequest) throws -> Topology {
        let sampleStride = isBarycentric ? 3 : 2
        let samplesBytes = samples.count * 4
        let indicesBytes = indices.count * 4
        guard let samplesBuffer = device.makeBuffer(bytes: samples, length: max(samplesBytes, 16), options: .storageModeShared) else {
            throw BridgeError.allocationFailed("Failed to allocate the domain sample buffer (\(samplesBytes) bytes).")
        }
        guard let indexBuffer = device.makeBuffer(bytes: indices, length: max(indicesBytes, 4), options: .storageModeShared) else {
            throw BridgeError.allocationFailed("Failed to allocate the tessellation index buffer (\(indicesBytes) bytes).")
        }
        let samplesPerPatch = samplesPerPatchOverride
        guard samplesPerPatch > 0, samplesPerPatch * sampleStride * patchCount == samples.count else {
            throw BridgeError.operationFailed("Internal error: sample count is not uniform across patches.")
        }
        return Topology(samplesBuffer: samplesBuffer,
                        indexBuffer: indexBuffer,
                        samplesPerPatch: samplesPerPatch,
                        indexCount: indices.count,
                        approximations: approximations)
    }

    /// Interprets one half-precision tessellation factor for the emulated path:
    /// fractional modes collapse to integer counts, factors below 1 still emit one
    /// segment (Apple culls at exactly 0; the bridge keeps that distinction by
    /// treating only non-positive factors as degenerate), and results clamp to the
    /// family maximum.
    private func partitionCount(_ raw: UInt16) -> Int {
        let value = Self.halfToFloat(raw)
        if value <= 0 { return 0 }
        let clamped = min(value, Float(self.maxTessellationFactor))
        return max(1, Int(clamped.rounded(.up)))
    }

    /// Exact IEEE half -> single conversion without `Float16`, which is unavailable
    /// on Intel macOS hosts. Subnormals scale by 2^-24, specials pass through, so the
    /// result is bit-identical to `Float(Float16(bitPattern:))`.
    static func halfToFloat(_ raw: UInt16) -> Float {
        let sign: Float = (raw & 0x8000) != 0 ? -1.0 : 1.0
        let exponent = Int((raw >> 10) & 0x1F)
        let fraction = Float(raw & 0x03FF)
        if exponent == 0 {
            if fraction == 0 { return sign * 0.0 } // +/- zero
            return sign * fraction * 0x1p-24 // half subnormal: fraction * 2^-24
        }
        if exponent == 31 {
            if fraction == 0 { return sign * Float.infinity }
            return Float.nan
        }
        return sign * (1.0 + fraction / 1024.0) * Self.pow2(exponent - 15)
    }

    /// `2^k` built from the float bit pattern so the result is exact for any
    /// representable exponent (k in [-126, 127]).
    static func pow2(_ k: Int) -> Float {
        return Float(bitPattern: UInt32(truncatingIfNeeded: (k + 127) << 23))
    }

    private func validateAllocation(_ bytes: Int) throws {
        guard bytes <= device.maxBufferLength else {
            throw BridgeError.allocationFailed("""
            Tessellated vertex stream needs \(bytes) bytes, exceeding maxBufferLength \
            (\(device.maxBufferLength)). Reduce patchCount or tessellation factors.
            """)
        }
    }

    // MARK: - Kernel plumbing

    private func pipelineState(for function: MTLFunction) throws -> MTLComputePipelineState {
        do {
            return try device.makeComputePipelineState(function: function)
        } catch {
            throw BridgeError.operationFailed("Domain kernel pipeline failed: \(error)")
        }
    }

    private func groupSize(for pipeline: MTLComputePipelineState, threads: MTLSize) -> MTLSize {
        let width = min(threads.width, pipeline.threadExecutionWidth)
        let height = max(1, min(pipeline.maxTotalThreadsPerThreadgroup / max(1, width), 8))
        return MTLSize(width: max(1, width),
                       height: height,
                       depth: 1)
    }

    private func frameworkLibrary() throws -> MTLLibrary {
        if let library = domainLibrary { return library }
        let bundle = Bundle(for: TessellationEmulator.self)
        guard let library = try? device.makeDefaultLibrary(bundle: bundle) else {
            throw BridgeError.unsupported("""
            The MetalBridgeKit framework metallib is unavailable. The tessellation \
            demo kernels are compiled into the framework; check that Shaders/*.metal \
            are part of the MetalBridgeKit target.
            """)
        }
        domainLibrary = library
        return library
    }
}

/// Mirrors struct TessDomainParams in Shaders/Tessellation.metal. Keep in sync.
struct TessDomainParamsLayout {
    var patchCount: UInt32 = 0
    var controlPointsPerPatch: UInt32 = 0
    var samplesPerPatch: UInt32 = 0
    var controlPointStride: UInt32 = 0
    var vertexStride: UInt32 = 0
    var patchType: UInt32 = 0
}
